e[data-v-716eb6c7]{color:#f0d48a;font-weight:bold}.mbx-del[data-v-716eb6c7]{background:transparent;border:none;color:#a2947c;cursor:pointer;font-size:13px;padding:2px 5px;border-radius:4px}.mbx-del[data-v-716eb6c7]:hover{color:#fca5a5;background:rgba(248,113,113,0.15)}.mbx-empty[data-v-716eb6c7]{font-size:12px;color:#9c8e76;text-align:center;padding:14px 0}.mbx-rule[data-v-716eb6c7]{display:flex;flex-direction:column;gap:5px;background:rgba(255,255,255,0.05);border:1px solid rgba(212,175,55,0.15);border-radius:8px;padding:8px}.mbx-rule .mbx-del[data-v-716eb6c7]{align-self:flex-end}.mbx-settings[data-v-716eb6c7]{display:flex;gap:14px;margin-top:4px}
`, "",{"version":3,"sources":["webpack://./src/音乐盒/App.vue"],"names":[],"mappings":"AAmOA,4BACE,UAAW,CACX,gBAAiB,CACjB,eAAgB,CAChB,cAAe,CACf,aACF,CAGA,2BACE,YAAa,CACb,OAAQ,CACR,kBAAmB,CACnB,6CAAiD,CACjD,kBACF,CACA,0BACE,sBAAuB,CACvB,WAAY,CACZ,aAAc,CACd,cAAe,CACf,cAAe,CACf,gBAAiB,CACjB,mBAAoB,CACpB,oBACF,CACA,gCACE,aACF,CACA,iCACE,+BAAmC,CACnC,aAAc,CACd,gBACF,CAEA,2BACE,YAAa,CACb,qBAAsB,CACtB,OACF,CAEA,0BACE,cAAe,CACf,gBAAiB,CACjB,aAAc,CACd,kBAAmB,CACnB,eAAgB,CAChB,sBACF,CACA,gCACE,aAAc,CACd,kBACF,CACA,4BACE,cAAe,CACf,aACF,CACA,kCACE,aACF,CAEA,2BACE,YAAa,CACb,sBAAuB,CACvB,kBAAmB,CACnB,QACF,CACA,0BACE,UAAW,CACX,WAAY,CACZ,iBAAkB,CAClB,qCAAyC,CACzC,gCAAoC,CACpC,aAAc,CACd,cAAe,CACf,cAAe,CACf,oBACF,CACA,gCACE,gCACF,CACA,+BACE,UAAW,CACX,WAAY,CACZ,cAAe,CACf,kDAAqD,CACrD,kCACF,CAEA,+BACE,UAAW,CACX,iBAAkB,CAClB,gCAAoC,CACpC,eACF,CACA,oCACE,WAAY,CACZ,iDAAoD,CACpD,qBACF,CAEA,0BACE,YAAa,CACb,kBAAmB,CACnB,OACF,CACA,2BACE,cACF,CACA,4BACE,MAAO,CACP,oBACF,CACA,0BACE,cAAe,CACf,UAAW,CACX,gBAAiB,CACjB,aACF,CAEA,iCACE,6BACF,CACA,4BACE,mBAAoB,CACpB,kBAAmB,CACnB,OAAQ,CACR,cAAe,CACf,aAAc,CACd,cACF,CACA,kCACE,oBACF,CACA,+BACE,gCAAoC,CACpC,sCAA0C,CAC1C,aAAc,CACd,mBAAoB,CACpB,gBAAiB,CACjB,cAAe,CACf,cACF,CACA,qCACE,gCACF,CAGA,0BACE,YAAa,CACb,kBAAmB,CACnB,OACF,CACA,4BACE,MAAO,CACP,WAAY,CACZ,iCAAqC,CACrC,qCAAyC,CACzC,iBAAkB,CAClB,eAAgB,CAChB,cAAe,CACf,aAAc,CACd,YACF,CACA,kCACE,oBACF,CACA,yCACE,aACF,CACA,6BACE,kDAAqD,CACrD,WAAY,CACZ,UAAW,CACX,iBAAkB,CAClB,gBAAiB,CACjB,cAAe,CACf,cAAe,CACf,kBACF,CACA,mCACE,sBACF,CACA,kCACE,UAAW,CACX,WACF,CACA,2BACE,mBAAoB,CACpB,kBAAmB,CACnB,gCAAoC,CACpC,sCAA0C,CAC1C,iBAAkB,CAClB,gBAAiB,CACjB,cAAe,CACf,aAAc,CACd,cACF,CACA,iCACE,gCACF,CACA,2BACE,cAAe,CACf,aAAc,CACd,eACF,CAEA,6BACE,gBAAiB,CACjB,eAAgB,CAChB,YAAa,CACb,qBAAsB,CACtB,OAAQ,CACR,cACF,CACA,4BACE,YAAa,CACb,kBAAmB,CACnB,6BAA8B,CAC9B,OAAQ,CACR,iCAAqC,CACrC,sCAA0C,CAC1C,iBAAkB,CAClB,eACF,CACA,kCACE,MAAO,CACP,WAAY,CACZ,kBAAmB,CACnB,eAAgB,CAChB,sBAAuB,CACvB,cAAe,CACf,aACF,CACA,wCACE,aACF,CACA,yCACE,aAAc,CACd,gBACF,CACA,0BACE,sBAAuB,CACvB,WAAY,CACZ,aAAc,CACd,cAAe,CACf,cAAe,CACf,eAAgB,CAChB,iBACF,CACA,gCACE,aAAc,CACd,iCACF,CACA,4BACE,cAAe,CACf,aAAc,CACd,iBAAkB,CAClB,cACF,CAGA,2BACE,YAAa,CACb,qBAAsB,CACtB,OAAQ,CACR,iCAAqC,CACrC,sCAA0C,CAC1C,iBAAkB,CAClB,WACF,CACA,oCACE,mBACF,CACA,+BACE,YAAa,CACb,QAAS,CACT,cACF","sourcesContent":["<template>\n  <FloatingPanelDemo\n    :expanded=\"panelState.expanded\"\n    :collapsed=\"panelState.collapsed\"\n    icon-type=\"music\"\n    color-theme=\"brown\"\n    shape=\"square\"\n    :animate=\"store.playing\"\n  >\n    <div class=\"mbx-shell\">\n      <!-- Tab 头 -->\n      <div class=\"mbx-tabs\">\n        <button\n          v-for=\"t in tabs\"\n          :key=\"t.id\"\n          class=\"mbx-tab\"\n          :class=\"{ active: tab === t.id }\"\n          @click=\"tab = t.id\"\n        >\n          {{ t.label }}\n        </button>\n      </div>\n\n      <!-- ============ 播放页 ============ -->\n      <div v-if=\"tab === 'play'\" class=\"mbx-pane\">\n        <div class=\"mbx-now\" :class=\"{ muted: !store.currentTrackTitle }\">\n          🎵 {{ store.currentTrackTitle || '未播放' }}\n        </div>\n        <div v-if=\"store.currentScene\" class=\"mbx-scene\">📍 场景：{{ store.currentScene }}</div>\n        <div v-else-if=\"store.settings.autoSwitch && !store.autoDisabled\" class=\"mbx-scene muted\">\n          🎧 等待场景变化…\n        </div>\n\n        <div class=\"mbx-btns\">\n          <button class=\"mbx-btn\" title=\"上一首\" @click=\"store.playNext(-1)\">⏮</button>\n          <button class=\"mbx-btn mbx-btn-main\" title=\"播放/暂停\" @click=\"store.togglePlay()\">\n            {{ store.playing ? '⏸' : '▶' }}\n          </button>\n          <button class=\"mbx-btn\" title=\"下一首\" @click=\"store.playNext(1)\">⏭</button>\n        </div>\n\n        <div class=\"mbx-progress\">\n          <div class=\"mbx-progress-fill\" :style=\"{ width: store.progress + '%' }\"></div>\n        </div>\n\n        <div class=\"mbx-row\">\n          <span class=\"mbx-icon\">🔉</span>\n          <input\n            class=\"mbx-range\"\n            type=\"range\"\n            min=\"0\"\n            max=\"100\"\n            :value=\"store.volume\"\n            @input=\"onVolume($event)\"\n          >\n          <span class=\"mbx-val\">{{ store.volume }}</span>\n        </div>\n\n        <div class=\"mbx-row mbx-switch-row\">\n          <label class=\"mbx-label\">\n            <input type=\"checkbox\" :checked=\"store.settings.autoSwitch && !store.autoDisabled\" @change=\"toggleAuto\">\n            场景自动切歌\n          </label>\n          <button class=\"mbx-mini-btn\" @click=\"store.detectAndApplyScene()\">🔄 立即检测</button>\n        </div>\n      </div>\n\n      <!-- ============ 列表页 ============ -->\n      <div v-if=\"tab === 'list'\" class=\"mbx-pane\">\n        <div class=\"mbx-add\">\n          <input\n            v-model=\"newUrl\"\n            class=\"mbx-input\"\n            placeholder=\"音乐直链 / 网易云歌曲链接\"\n            @keyup.enter=\"addByUrl\"\n          >\n          <button class=\"mbx-addbtn\" @click=\"addByUrl\">添加</button>\n        </div>\n        <div class=\"mbx-hint\">🎵 支持：音频直链 或 网易云歌曲链接（music.163.com/song?id=…，含 #/ 格式）自动解析（VIP 曲目会失败）</div>\n        <div class=\"mbx-add\">\n          <label class=\"mbx-file\">\n            📁 选择本地音频文件\n            <input type=\"file\" accept=\"audio/*\" style=\"display:none\" @change=\"onFile\">\n          </label>\n          <span class=\"mbx-hint\">建议 ≤ 5MB</span>\n        </div>\n        <div class=\"mbx-tracks\">\n          <div v-for=\"(t, i) in store.tracks\" :key=\"i\" class=\"mbx-track\">\n            <span\n              class=\"mbx-track-title\"\n              :class=\"{ active: t.title === store.currentTrackTitle }\"\n              title=\"点击播放\"\n              @click=\"store.playTrack(t)\"\n            >\n              {{ t.source === 'file' ? '📁' : (t.source === 'netease' ? '🎵' : '🔗') }} {{ t.title }}\n            </span>\n            <button class=\"mbx-del\" title=\"删除\" @click=\"store.removeTrack(i)\">✕</button>\n          </div>\n          <div v-if=\"!store.tracks.length\" class=\"mbx-empty\">\n            暂无音乐。添加网络链接、网易云链接，或上传本地音频文件。\n          </div>\n        </div>\n      </div>\n\n      <!-- ============ 场景页 ============ -->\n      <div v-if=\"tab === 'scene'\" class=\"mbx-pane\">\n        <div class=\"mbx-hint\">\n          检测源：角色变量（{{ store.settings.varPaths.join('、') }}）＋ 最近消息关键词。\n          命中关键词 → 自动播放绑定曲目。\n        </div>\n        <div v-for=\"(r, i) in store.sceneRules\" :key=\"i\" class=\"mbx-rule\">\n          <input v-model=\"r.name\" class=\"mbx-input\" placeholder=\"场景名（如：酒馆）\" @change=\"store.saveToVariables()\">\n          <input v-model=\"r.keywordsText\" class=\"mbx-input\" placeholder=\"关键词，逗号分隔（如：酒馆、吧台）\" @change=\"store.saveToVariables()\">\n          <select v-model=\"r.trackTitle\" class=\"mbx-input\" @change=\"store.saveToVariables()\">\n            <option value=\"\">— 绑定曲目 —</option>\n            <option v-for=\"t in store.tracks\" :key=\"t.title\" :value=\"t.title\">{{ t.title }}</option>\n          </select>\n          <button class=\"mbx-del\" title=\"删除规则\" @click=\"store.removeSceneRule(i)\">✕</button>\n        </div>\n        <button class=\"mbx-addbtn mbx-addbtn-wide\" @click=\"addRule\">＋ 添加场景规则</button>\n        <div class=\"mbx-settings\">\n          <label class=\"mbx-label\">\n            <input type=\"checkbox\" v-model=\"store.settings.checkVariables\" @change=\"store.saveToVariables()\">\n            变量通道\n          </label>\n          <label class=\"mbx-label\">\n            <input type=\"checkbox\" v-model=\"store.settings.checkMessages\" @change=\"store.saveToVariables()\">\n            消息通道\n          </label>\n        </div>\n      </div>\n    </div>\n  </FloatingPanelDemo>\n</template>\n\n<script setup lang=\"ts\">\nimport { ref } from 'vue';\nimport FloatingPanelDemo from '../悬浮按钮/FloatingPanelDemo.vue';\nimport { useMusicBoxStore } from './store';\n\ndefineProps<{\n  panelState: { expanded: boolean; collapsed: boolean };\n}>();\n\nconst store = useMusicBoxStore();\n\nconst tabs = [\n  { id: 'play', label: '播放' },\n  { id: 'list', label: '列表' },\n  { id: 'scene', label: '场景' },\n];\nconst tab = ref('play');\n\nconst newUrl = ref('');\nconst resolvingNetease = ref(false);\n\nasync function addByUrl(): Promise<void> {\n  const url = newUrl.value.trim();\n  if (!url) return;\n  newUrl.value = '';\n\n  // 网易云链接识别：https://music.163.com/song?id=xxx 或 /#/song?id=xxx\n  const m = url.match(/music\\.163\\.com\\/(?:#\\/)?song\\?id=(\\d+)/);\n  if (m) {\n    const songId = m[1];\n    if (resolvingNetease.value) return;\n    resolvingNetease.value = true;\n    if (typeof toastr !== 'undefined') toastr.info('正在解析网易云链接…', '音乐盒');\n    const track = await store.resolveNeteaseTrack(songId);\n    resolvingNetease.value = false;\n    if (track) {\n      if (typeof toastr !== 'undefined') toastr.success(`已添加「${track.title}」`, '音乐盒');\n    } else {\n      if (typeof toastr !== 'undefined') {\n        toastr.error('网易云解析失败：可能是 VIP 曲目/无版权，或解析服务暂时不可用。请换一首免费歌曲试试，或直接提供音频直链', '音乐盒');\n      }\n    }\n    return;\n  }\n\n  store.addTrack({ url });\n  if (typeof toastr !== 'undefined') toastr.success('已添加音乐', '音乐盒');\n}\n\nfunction onFile(e: Event): void {\n  const input = e.target as HTMLInputElement;\n  const file = input.files?.[0];\n  if (!file) return;\n  if (file.size > 8 * 1024 * 1024) {\n    if (typeof toastr !== 'undefined') toastr.error('文件过大（>8MB），请使用网络链接', '音乐盒');\n    input.value = '';\n    return;\n  }\n  const reader = new FileReader();\n  reader.onload = () => {\n    store.addTrack({\n      title: file.name.replace(/\\.[a-z0-9]+$/i, ''),\n      url: String(reader.result || ''),\n      source: 'file',\n    });\n    if (typeof toastr !== 'undefined') toastr.success(`已添加「${file.name}」`, '音乐盒');\n  };\n  reader.onerror = () => {\n    if (typeof toastr !== 'undefined') toastr.error('文件读取失败', '音乐盒');\n  };\n  reader.readAsDataURL(file);\n  input.value = '';\n}\n\nfunction addRule(): void {\n  store.addSceneRule({ name: `场景${store.sceneRules.length + 1}` });\n}\n\nfunction onVolume(e: Event): void {\n  const v = Number((e.target as HTMLInputElement).value);\n  store.setVolume(v);\n}\n\nfunction toggleAuto(e: Event): void {\n  const checked = (e.target as HTMLInputElement).checked;\n  store.settings.autoSwitch = checked;\n  store.autoDisabled = !checked;\n  store.saveToVariables();\n}\n</script>\n\n<style scoped>\n.mbx-shell {\n  width: 100%;\n  max-height: 460px;\n  overflow-y: auto;\n  font-size: 13px;\n  color: #eadfc8;\n}\n\n/* Tab */\n.mbx-tabs {\n  display: flex;\n  gap: 4px;\n  margin-bottom: 10px;\n  border-bottom: 1px solid rgba(212, 175, 55, 0.28);\n  padding-bottom: 6px;\n}\n.mbx-tab {\n  background: transparent;\n  border: none;\n  color: #b8a88f;\n  font-size: 13px;\n  cursor: pointer;\n  padding: 4px 12px;\n  border-radius: 999px;\n  transition: all 0.15s;\n}\n.mbx-tab:hover {\n  color: #f0d48a;\n}\n.mbx-tab.active {\n  background: rgba(212, 175, 55, 0.2);\n  color: #f0d48a;\n  font-weight: bold;\n}\n\n.mbx-pane {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n\n.mbx-now {\n  font-size: 14px;\n  font-weight: bold;\n  color: #f0d48a;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n.mbx-now.muted {\n  color: #9c8e76;\n  font-weight: normal;\n}\n.mbx-scene {\n  font-size: 12px;\n  color: #d9b96a;\n}\n.mbx-scene.muted {\n  color: #9c8e76;\n}\n\n.mbx-btns {\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  gap: 10px;\n}\n.mbx-btn {\n  width: 40px;\n  height: 40px;\n  border-radius: 50%;\n  border: 1px solid rgba(212, 175, 55, 0.4);\n  background: rgba(212, 175, 55, 0.12);\n  color: #f0d48a;\n  font-size: 16px;\n  cursor: pointer;\n  transition: all 0.15s;\n}\n.mbx-btn:hover {\n  background: rgba(212, 175, 55, 0.25);\n}\n.mbx-btn-main {\n  width: 52px;\n  height: 52px;\n  font-size: 20px;\n  background: linear-gradient(135deg, #c9a35a, #8a6a52);\n  border-color: rgba(240